import java.util.*;
public class C_Bear_And_Company_3 {

    static int cv, ck , cs;
    static int[][] freq;
    static ArrayList<Integer>[] pos;
    static int[][][][] dp;

    public static void main(String[] agrs) {
    	Scanner in = new Scanner(System.in);
        int n = in.nextInt();
        char[] c = in.next().toCharArray();
        cv = 0;
        ck = 0;
        cs = 0;
        freq = new int[n + 1][3];
        pos = new ArrayList[3];
        for (int i = 0; i < 3; i++) pos[i] = new ArrayList<>();
        int idx = 0;
        for (char x : c) {
            System.arraycopy(freq[idx], 0, freq[idx + 1], 0, 3);
            idx++;
            if (x == 'V') {
                freq[idx][0]++;
                cv++;
                pos[0].add(idx);
            } else if (x == 'K') {
                freq[idx][1]++;
                ck++;
                pos[1].add(idx);
            } else {
                freq[idx][2]++;
                cs++;
                pos[2].add(idx);
            }
        }
        dp = new int[cv + 1][ck + 1][cs + 1][3];
        for (int[][][] x : dp) for (int[][] y : x) for (int[] z : y) Arrays.fill(z, -1);
        System.out.println(dfs(0, 0, 0, 2));
    }

    static int dfs(int tv, int tk, int ts, int last) {
        if (tv == cv && tk == ck && ts == cs) {
            return 0;
        }
        if (dp[tv][tk][ts][last] != -1) return dp[tv][tk][ts][last];
        int ret = 1 << 29;
        if (tv < cv) {
            int p = pos[0].get(tv);
            int move = Math.max(freq[p][0] - tv, 0) + Math.max(freq[p][1] - tk, 0) + Math.max(freq[p][2] - ts, 0) - 1;
            ret = Math.min(ret, dfs(tv + 1, tk, ts, 0) + move);
        }
        if (tk < ck && last != 0) {
            int p = pos[1].get(tk);
            int move = Math.max(freq[p][0] - tv, 0) + Math.max(freq[p][1] - tk, 0) + Math.max(freq[p][2] - ts, 0) - 1;
            ret = Math.min(ret, dfs(tv, tk + 1, ts, 1) + move);
        }
        if (ts < cs) {
            int p = pos[2].get(ts);
            int move = Math.max(freq[p][0] - tv, 0) + Math.max(freq[p][1] - tk, 0) + Math.max(freq[p][2] - ts, 0) - 1;
            ret = Math.min(ret, dfs(tv, tk, ts + 1, 2) + move);
        }
        return dp[tv][tk][ts][last] = ret;
    }

}

